'use strict';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const number=n=>(n??0).toLocaleString('en-US');
function safeHref(raw){try{const u=new URL(String(raw||''));return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
function sourceUrl(r){return meta.mode==='synthetic demo'?'':safeHref(r.comment_url||'https://www.regulations.gov/comment/'+encodeURIComponent(r.comment_id));}
let meta={}, themes=[], queryPage=1, explorerPage=1, lastReviewText='';
const sections={ feedback:['FORM LETTERS & TOPICS','Explore distinct concerns.','Screen near-duplicate letters, primary topic relevance and substantive recommendations.'],management:['MANAGEMENT SYNTHESIS','Classify and synthesize response themes.','An additive source-grounded view aligned to management’s eight reporting headings.'], 'local-ai':['OPENAI ANALYSIS','Ask questions with source evidence.','Database-backed counts with optional paid OpenAI summaries; no automatic API calls.'],overview:['CORPUS OVERVIEW','What are commenters saying?','Explore the imported public record, track completeness, and inspect provisional themes.'],semantic:['MODEL CLASSIFICATION','AI-labeled comment themes.','Resumable full-corpus coding, evidence, and review queue; not human-validated.'],query:['QUESTION & EVIDENCE','Find evidence, not guesses.','Search the full imported text and report traceable counts of comment records.'],themes:['THEME FREQUENCY','Map the issues being raised.','Screening counts and direct drill-through to the original public comments.'],explorer:['SOURCE DOCUMENTS','Every count has a record.','Browse original comments, follow source links, and review classifications.'],qc:['SOURCE QC','What needs verification?','Reconcile the public record, detect repeated submissions, and triage coverage gaps.'],review:['DRAFT RESPONSE REVIEW','What might the draft miss?','A first-pass screening worksheet for substantive analyst verification.'],imports:['DATA MANAGEMENT','Import once. Refresh anytime.','Load cumulative exporter files and generate downloadable review tables.']};
async function api(path, options={}){const res=await fetch(path,{cache:'no-store',...options});let body;if(res.headers.get('content-type')?.includes('application/json'))body=await res.json();else body=await res.text();if(!res.ok)throw Error(body?.error||`HTTP ${res.status}`);return body;}
function msg(text,error=false){const el=$('message');el.textContent=text;el.className='message'+(error?' error':'');clearTimeout(msg.timer);msg.timer=setTimeout(()=>el.classList.add('hide'),10000);}
function showTab(tab){document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));document.querySelectorAll('.tabpanel').forEach(e=>e.classList.toggle('hide',e.id!==`tab-${tab}`));const [eyebrow,title,desc]=sections[tab];$('sectionEyebrow').textContent=eyebrow;$('sectionTitle').textContent=title;$('sectionDesc').textContent=desc;history.replaceState(null,'','#'+tab);if(tab==='management')renderManagement();if(tab==='feedback')renderFeedback();if(tab==='semantic')refreshSemantic();if(tab==='explorer')loadExplorer();if(tab==='themes')renderThemeRows();if(tab==='qc')renderQc();scrollTo({top:0,behavior:'instant'});}
const item=(t,max)=>`<button class="theme-item" type="button" data-theme="${esc(t.id)}" aria-label="View ${esc(t.name)} comments"><div class="bar-meta"><span class="theme-name">${esc(t.name)}</span><span class="bar-count">${number(t.count)}<small class="distinct" title="Approximate text groups: near-duplicate form-letter clusters counted once"> · ${number(t.distinct_texts)} text groups</small></span></div><div class="track"><div class="fill" style="width:${max?100*t.count/max:0}%"></div></div></button>`;
function renderThemeRows(){const max=Math.max(1,...themes.map(x=>x.count));$('overviewThemes').innerHTML=themes.length?themes.slice(0,7).map(t=>item(t,max)).join(''):'No themes available';$('themeRows').innerHTML=themes.length?themes.map(t=>`${item(t,max)}<div class="theme-sub">${esc(t.description||'')}</div>`).join(''):'No themes available';}
function metric(title,value){return `<div class="metric"><span>${esc(title)}</span><strong>${esc(value)}</strong></div>`;}
function renderMeta(){
 $('kRecords').textContent=number(meta.records);$('kText').textContent=number(meta.with_text);$('kThemes').textContent=number(meta.themes);$('kDuplicate').textContent=number(meta.distinct_texts);$('kDuplicateSub').textContent=`${number(meta.records_in_form_letter_clusters)} records in ${number(meta.form_letter_clusters)} form-letter clusters`;
 const sample=meta.mode==='synthetic demo';const partial=meta.indexed_count&&meta.records<meta.indexed_count;
 const banner=$('statusBanner');
 if(!meta.records){banner.className='banner warning';banner.innerHTML='No comments loaded. Import your saved <code>comments.csv</code> or try the clearly labeled synthetic demonstration.';}
 else if(sample){banner.className='banner demo';banner.innerHTML='<strong>SYNTHETIC DEMO DATA.</strong> These comments were invented solely for testing. They are NOT real submissions and must not be reported to management.';}
 else if(partial){banner.className='banner warning';banner.textContent=`PARTIAL EXPORT · ${number(meta.records)} of ${number(meta.indexed_count)} indexed records loaded. Counts exclude comments not yet downloaded. All classifications are provisional.`;}
 else {banner.className='banner info';banner.textContent=meta.private_preview?`PRIVATE LOCAL SNAPSHOT · ${number(meta.records)} source records; complete against the October 21, 2026 API index (not later submissions). Management labels are AI-adjudicated but not independently human-validated; see questionable CSV.`:`Imported ${number(meta.records)} comment records. API/website completeness has NOT yet been independently verified; screening classifications require QC.`;}
 $('integrity').innerHTML=[metric('Imported comment records',number(meta.records)),metric('Indexed records at export time',meta.indexed_count===null?'Not provided':number(meta.indexed_count)),metric('API total at index time',meta.api_total_at_index_time===null?'Not provided':number(meta.api_total_at_index_time)),metric('Records without body text',number(meta.blank_text)),metric('Substance likely in attachment',number(meta.attachment_only_placeholders)),metric('Comments listing attachments',number(meta.comment_records_with_declared_attachments)),metric('Unclassified by keyword screen',number(meta.unclassified_keyword_records)),metric('Attachment documents (file renditions)',`${number(meta.attachment_documents)} (${number(meta.attachment_metadata_rows)})`),metric('Attachment documents with extracted text',number(meta.attachment_documents_with_extracted_text)),metric('Attachments reviewed with no written text',number(meta.attachment_documents_reviewed_without_text||0)),metric('Largest form-letter cluster',number(meta.largest_cluster_size)+' records'),metric('Personalized form letters',number(meta.personalized_form_letters)),metric('Unfilled template placeholders',number(meta.unfilled_template_placeholders)),metric('Same-name identical resubmissions',number(meta.same_submitter_extra_records)+' extra records'),metric('Possible source truncation',number(meta.possible_truncation)),metric('Records in exact-duplicate groups',number(meta.records_in_duplicate_groups)),metric('Classification status','Unvalidated screening ('+(meta.taxonomy_version||'')+')'),metric('Last local import',meta.imported_at_utc||'—')].join('');
}
function populateThemes(){for(const id of ['queryTheme','explorerTheme']){const sel=$(id),v=sel.value;sel.innerHTML='<option value="">'+(id==='queryTheme'?'All themes':'All comments')+'</option>'+themes.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('');sel.value=v;}
for(const id of ['localTheme','localReviewTheme']){const sel=$(id);if(!sel)continue;const old=sel.value;sel.innerHTML='<option value="">'+(id==='localTheme'?'No theme — lexical record screening':'Choose a theme')+'</option>'+themes.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('');sel.value=old;}}
async function refresh(){try{[meta,{themes}]=await Promise.all([api('/api/meta'),api('/api/themes')]);populateThemes();if(meta.hosted_readonly){
  $('importButton').disabled=true;document.body.classList.add('hosted');if(meta.private_preview)document.body.classList.add('private-preview');
  $('importShortcut').textContent='Download reports';document.querySelector('.nav[data-tab="imports"]').lastChild.textContent=' Downloads & reports';
  $('localModel').closest('label').style.display='none';
  $('openaiConsent').closest('label').style.display='none';
  $('localRefreshModels').style.display='none';
  sections['local-ai']=['EVIDENCE SEARCH','Ask questions about source comments.','Evidence-only search, saved classifications and source-linked records. No paid API calls on this host.'];
  sections['imports']=['EXPORTS','Download verified source records.','Source metadata, evidence and QC reports; no hosted data editing.'];
  document.querySelector('#tab-local-ai .panelhead p').textContent='Search the indexed public comments and inspect original source evidence. No paid API calls from the hosted demo.';$('localModelStatus').className='banner info';$('localModelStatus').textContent=(meta.private_preview?'Private local preview':'Public read-only demo')+': evidence search only. No paid OpenAI calls are made.';
  document.querySelector('.top-state').textContent=meta.private_preview?'PRIVATE LOCAL PREVIEW · Read-only · No API charges':'Public · Read-only · No API charges';
  document.querySelector('.sidebar-note').textContent=(meta.private_preview?'PRIVATE local preview. ':'Public read-only demo. ')+'3,748 source-current coded comments; management labels AI-adjudicated provisionally, 62 specifically flagged for optional source review. Not human-validated.';
}renderMeta();renderThemeRows();await sourceRefresh(); if(!$('tab-qc').classList.contains('hide'))await renderQc();}catch(e){msg('Cannot load local data: '+e.message,true);}}
async function sourceRefresh(){try{const d=await api('/api/source');$('configuredSource').textContent=meta.hosted_readonly?(meta.private_preview?'Private frozen snapshot · refresh is disabled here.':'Shared demo snapshot · data refresh is disabled here.'):d.path + (d.available?'  •  comments.csv found':'  •  not accessible here; use the manual import or edit SOURCE_FOLDER.txt');$('syncButton').disabled=!d.available || Boolean(meta.hosted_readonly);}catch(e){$('configuredSource').textContent='Source status unavailable: '+e.message;$('syncButton').disabled=true;}}
async function syncCorpus(){if(!confirm('Replace dashboard snapshot with all cumulative comment records currently in your configured exporter CSV? Any manual edits to unchanged comments are preserved.'))return;const btn=$('syncButton');btn.disabled=true;btn.textContent='Refreshing from local files…';try{const d=await api('/api/sync',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirm:true})});await refresh();msg('Loaded '+number(d.records)+' comment records and '+number(d.attachments)+' attachment metadata rows. Snapshot replaced; no duplicate imports.');showTab('overview');}catch(e){msg('Refresh did not finish: '+e.message,true);}finally{btn.textContent='Refresh from exporter folder';await sourceRefresh();}}

function commentCard(r){const source=sourceUrl(r);const author=[r.first_name,r.last_name].filter(Boolean).join(' ')||r.organization||'Submitter not specified';let preview=String(r.plain_text||r.comment_text||'').slice(0,470);if(String(r.plain_text||r.comment_text||'').length>470)preview+='…';if(!preview)preview='No text in CSV. Check any attachments.';
return `<article class="comment-card"><div class="comment-meta"><span>${esc(r.posted_date||r.received_date||'Date not provided')} · ${esc(author)}</span>${source?`<a href="${esc(source)}" target="_blank" rel="noopener noreferrer">Source ↗</a>`:'<span>Synthetic / no source link</span>'}</div><div class="comment-title">${esc(r.title||r.comment_id)}</div><div class="comment-snippet">${esc(preview)}</div><div class="card-actions"><button class="open-detail" data-id="${esc(r.comment_id)}">Read full comment and tags →</button></div></article>`;}
function pagerHtml(total,page,divId){if(!total)return '';const pages=Math.ceil(total/20);return `<button data-page="${page-1}" ${page===1?'disabled':''} class="previous">← Previous</button><span>Page ${page} of ${number(pages)}</span><button data-page="${page+1}" ${page>=pages?'disabled':''} class="next">Next →</button>`;}
function paramsFrom(type){if(type==='query')return {q:$('queryInput').value.trim(),theme:$('queryTheme').value,match:$('queryMode').value,form_mode:$('queryFormMode').value};return {q:$('explorerQ').value.trim(),theme:$('explorerTheme').value,match:$('explorerMode').value,form_mode:$('explorerFormMode').value};}
function urlParams(data){return new URLSearchParams(Object.fromEntries(Object.entries(data).filter(([k,v])=>v!==''&&v!==undefined))).toString();}
async function runQuery(page=1){try{queryPage=page;let q=paramsFrom('query');const result=await api('/api/comments?'+urlParams({...q,page,size:20}));$('queryResult').innerHTML=`<div class="resultheadline">${number(result.total)} matching records in current snapshot</div><p class="footnote">The search counts records, not people. “Any” searches literal tokens, while a selected theme uses provisional assignments. Results may omit related comments expressed in different words.</p><div class="actions"><button class="button subtle" id="queryCsvBtn">Download matching records ↓</button></div>`;$('queryCards').innerHTML=result.comments.length?result.comments.map(commentCard).join(''):'<div class="muted">No matching records. Try a broader term or another theme.</div>';$('queryPager').innerHTML=pagerHtml(result.total,page);$('queryCsvBtn').onclick=()=>download('query_matches','query');}catch(e){msg(e.message,true);}}
async function loadExplorer(page=1){try{explorerPage=page;const result=await api('/api/comments?'+urlParams({...paramsFrom('explorer'),page,size:20}));$('explorerTotal').textContent=`${number(result.total)} matching comment records`;$('explorerCards').innerHTML=result.comments.length?result.comments.map(commentCard).join(''):'<div class="muted">No matching records.</div>';$('explorerPager').innerHTML=pagerHtml(result.total,page);}catch(e){msg(e.message,true);}}
async function openDetail(cid){try{const r=await api('/api/comment/'+encodeURIComponent(cid));const source=sourceUrl(r);$('detailTitle').textContent=r.title||r.comment_id;let tags=r.themes.map(t=>meta.hosted_readonly?`<span class="tag ${t.active?'active':''}" title="${t.keyword?esc('Matched: '+t.keyword+(t.source==='attachment'?' (in attachment text)':'')+'. '):''}Provisional screening label">${t.active?'✓ ':''}${esc(t.name)}${t.source==='attachment'?' 📎':''}</span>`:`<button class="tag ${t.active?'active':''} ${t.method==='manual'?'manual':''}" data-override-id="${esc(cid)}" data-override-theme="${esc(t.id)}" data-active="${t.active?'1':'0'}" title="${t.keyword?esc('Matched: '+t.keyword+(t.source==='attachment'?' (in attachment text)':'')+'. '):''}Click to ${t.active?'remove':'add'} theme for this comment">${t.active?'✓ ':''}${esc(t.name)}${t.source==='attachment'?' 📎':''}</button>`).join('');
const cl=r.cluster;const clusterHtml=cl&&cl.cluster_size>1?`<div class="banner info"><strong>Form-letter group: ${esc(cl.subject||'Subject not yet reviewed')}</strong><div>${esc(cl.subject_summary||'')}</div><small>Near-identical to ${number(cl.cluster_size-1)} other record(s) (group ${esc(cl.cluster_id)})${cl.personalized?' · this copy adds ~'+number(cl.novel_words)+' words of its own':''}${cl.unfilled_placeholder?' · template placeholder left unfilled':''}. Provisional subject summary.</small></div>`:'';$('detailBody').innerHTML=`<p class="muted">Comment ${esc(cid)} · ${esc(r.posted_date||'No date')} · ${esc(r.organization||[r.first_name,r.last_name].filter(Boolean).join(' ')||'Unknown submitter')}</p>${source?`<p><a class="source-link" target="_blank" rel="noopener noreferrer" href="${esc(source)}">Open original Regulations.gov record ↗</a></p>`:'<p class="muted">Synthetic test record; no original public comment exists.</p>'}${clusterHtml}<div class="detailtext">${esc(r.plain_text||r.comment_text||'[No text in export — see attachment metadata]')}</div><h3>Provisional themes</h3><p class="muted">${meta.hosted_readonly?'Provisional screening labels shown for inspection only. The read-only dashboard cannot change them.':'Click a theme to add/remove it manually for this comment. Dashed tags represent analyst overrides.'}</p><div class="tags">${tags}</div>${meta.hosted_readonly?'':`<h3>Analyst review</h3><p class="footnote">Local annotation; not a model judgment and not a validation of the whole corpus.</p><div class="field"><label for="analystStatus">Review status</label><select id="analystStatus"><option value="Not reviewed">Not reviewed</option><option value="Reviewed">Reviewed</option><option value="Needs follow-up">Needs follow-up</option></select></div><div class="field"><label for="analystNotes">Notes / unresolved concerns</label><textarea id="analystNotes" rows="3" maxlength="15000" placeholder="Evidence checked, classification correction, or follow-up needed..."></textarea></div><button class="button subtle" id="saveAnalystReview">Save review notes</button>`}<h3>Attachments listed (${r.attachments.length})</h3>${r.attachments.length?r.attachments.map(a=>`<p>${safeHref(a.download_url)?`<a target="_blank" rel="noopener noreferrer" href="${esc(safeHref(a.download_url))}">${esc(a.title||a.filename||a.attachment_id||'Attachment')} ↗</a>`:esc(a.title||a.filename||a.attachment_id||'Attachment (no URL)')}</p>`).join(''):'<p class="muted">No attachments in imported attachment metadata.</p>'}`;if(!meta.hosted_readonly){$('analystStatus').value=r.analyst_review?.review_status||'Not reviewed';$('analystNotes').value=r.analyst_review?.notes||'';$('saveAnalystReview').onclick=()=>saveAnalystReview(cid);}if(!$('commentDialog').open)$('commentDialog').showModal();}catch(e){msg(e.message,true);}}
async function saveAnalystReview(cid){try{await api('/api/analyst_review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({comment_id:cid,review_status:$('analystStatus').value,notes:$('analystNotes').value})});await refresh();msg('Analyst review saved locally.');}catch(e){msg(e.message,true);}}
async function overrideTheme(cid,theme,active){try{await api('/api/override',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({comment_id:cid,theme_id:theme,decision:active?0:1})});await refresh();await openDetail(cid);msg('Saved analyst correction locally.');}catch(e){msg(e.message,true);}}
async function reviewDraft(){try{lastReviewText=$('draftInput').value;const d=await api('/api/review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({draft:lastReviewText})});$('reviewResults').innerHTML=`<p class="footnote">${esc(d.limitations)}</p>`+d.rows.map(r=>`<div class="review-card ${r.draft_match?'match':'flag'}"><div class="review-card-title"><span>${esc(r.theme)}</span><span class="pill ${r.draft_match?'':'alert'}">${r.draft_match?'Keyword present':'No keyword signal'}</span></div><div class="review-card-sub">${number(r.comment_records)} flagged comment records · ${esc(r.analyst_status)}</div><div class="review-card-sub">Examples: ${r.example_comment_ids.map(x=>`<button class="textbutton open-detail" data-id="${esc(x)}">${esc(x)}</button>`).join(', ')||'None'}</div></div>`).join('');if(!d.rows.length)$('reviewResults').innerHTML='<p class="muted">No flagged themes from the imported comments.</p>';}catch(e){msg(e.message,true);}}
function download(kind,type=''){let d={kind};if(kind==='query_matches')d={...d,...paramsFrom(type||'query')};window.location.href='/api/export?'+urlParams(d);}
async function exportReview(){try{const draft=$('draftInput').value;if(draft.trim().length<25)throw Error('Paste at least 25 characters of response text first.');const response=await fetch('/api/export_review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({draft})});if(!response.ok){const err=await response.json();throw Error(err.error||'Export failed');}const blob=await response.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=(meta.mode==='synthetic demo'?'SYNTHETIC_TEST_':'')+'nhis_response_review.csv';a.click();URL.revokeObjectURL(url);}catch(e){msg(e.message,true);}}
const readFile=el=>el.files?.[0]?.text()??Promise.resolve('');
async function importFiles(){const btn=$('importButton');if(!$('fileComments').files.length){msg('Select comments.csv first.',true);return;}btn.disabled=true;btn.textContent='Validating & importing…';try{const [comments_csv,attachments_csv,index_json,status_json]=await Promise.all(['fileComments','fileAttachments','fileIndex','fileStatus'].map(id=>readFile($(id))));const result=await api('/api/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({comments_csv,attachments_csv,index_json,status_json,allow_smaller:$('allowSmaller').checked})});await refresh();msg(`Imported ${number(result.records)} comment records, ${number(result.attachments)} attachment metadata rows. Previous snapshot replaced; no duplicates added.`);showTab('overview');}catch(e){msg('Import cancelled: '+e.message,true);}finally{btn.disabled=false;btn.textContent='Import / refresh corpus';}}
function clickTheme(theme){$('explorerTheme').value=theme;$('explorerQ').value='';showTab('explorer');}
function delegate(evt){const theme=evt.target.closest('[data-theme]');if(theme){clickTheme(theme.dataset.theme);return;}const detail=evt.target.closest('[data-id].open-detail');if(detail){openDetail(detail.dataset.id);return;}const override=evt.target.closest('[data-override-id]');if(override){if(meta.hosted_readonly){msg('This dashboard is read-only. Corrections belong in a separately managed review workflow.',true);return;}overrideTheme(override.dataset.overrideId,override.dataset.overrideTheme,override.dataset.active==='1');return;}const pg=evt.target.closest('[data-page]');if(pg){if(evt.target.closest('#queryPager'))runQuery(Number(pg.dataset.page));else if(evt.target.closest('#explorerPager'))loadExplorer(Number(pg.dataset.page));return;}const exp=evt.target.closest('[data-export]');if(exp){download(exp.dataset.export,exp.dataset.export==='query_matches'?'query':'');}}
async function renderQc(){try{const q=await api('/api/qc');
 $('qcMeasures').innerHTML=[metric('Public comment records in this snapshot',number(q.records)),metric('Saved public API index',q.indexed_count===null?'Not provided':number(q.indexed_count)),metric('Not downloaded from saved index',q.indexed_missing===null?'Unknown':number(q.indexed_missing)),metric('Saved index timestamp',q.index_snapshot_time||'Not supplied'),metric('Approximate text groups (near-duplicate form letters combined)',number(q.distinct_texts)),metric('Form-letter clusters',number(q.shared_opening_group_count)),metric('Records in form-letter clusters',number(q.shared_opening_records)),metric('Largest cluster',number(q.largest_cluster_size)),metric('Personalized form letters',number(q.personalized_form_letters)),metric('Unfilled template placeholders',number(q.unfilled_template_placeholders)),metric('Same-name identical resubmissions',`${number(q.same_submitter_extra_records)} extra records in ${number(q.same_submitter_duplicate_groups)} groups`),metric('Attachment documents / with extracted text',`${number(q.attachment_documents)} / ${number(q.attachment_documents_with_extracted_text)}`),metric('Records whose substance is likely in an attachment',number(q.attachment_dependent_records)),metric('Possible source truncation',number(q.possible_truncation)),metric('Marked reviewed by analyst',number(q.analyst_reviewed)),metric('Needs analyst follow-up',number(q.analyst_needs_followup)),metric('Theme labels','Unvalidated')].join('');
 const mx=Math.max(1,...q.daily_postings.map(a=>a.count));
 $('qcDates').innerHTML=q.daily_postings.map(d=>`<div class="bar-meta"><span>${esc(d.day)}</span><strong>${number(d.count)}</strong></div><div class="track"><div class="fill" style="width:${100*d.count/mx}%"></div></div>`).join('');
 $('qcTemplates').innerHTML=q.shared_opening_groups.length?q.shared_opening_groups.map(g=>`<div class="review-card"><div class="review-card-title"><strong>${esc(g.subject||'Subject not yet reviewed')}</strong></div><div class="review-card-sub">${esc(g.subject_summary||'')}</div><div class="review-card-sub"><strong>${number(g.size)} near-identical comments</strong> · ${number(g.personalized)} personalized${g.unfilled_placeholders?' · '+number(g.unfilled_placeholders)+' unfilled template placeholders':''}</div><div class="footnote">Representative text: ${esc(g.shared_opening)}…</div><div class="review-card-sub">Example IDs: ${g.example_comment_ids.map(x=>`<button class="textbutton open-detail" data-id="${esc(x)}">${esc(x)}</button>`).join(' · ')}</div><div class="footnote">${esc(g.subject_status||'Provisional subject summary')}</div></div>`).join(''):'<p class="muted">No form-letter clusters detected.</p>';
 $('qcQueue').innerHTML=q.review_queue.slice(0,20).map(r=>`<div class="review-card"><button class="textbutton open-detail" data-id="${esc(r.comment_id)}">${esc(r.comment_id)}</button> · ${number(r.screened_theme_count)} keyword themes · <span class="pill alert">${esc(r.reasons||'')}</span><div class="review-card-sub">${esc(r.preview)}</div></div>`).join('');
 }catch(e){msg('QC view failed: '+e.message,true);}}

// The browser talks ONLY to the loopback Python server; the server alone calls api.openai.com, and only after explicit consent.
async function refreshLocalModels(){
 const status=$('localModelStatus');try{
 const r=await api('/api/local/status');
 if(meta?.hosted_readonly||document.body.classList.contains('hosted')){status.className='banner info';status.textContent=(meta?.private_preview?'Private local preview':'Public read-only demo')+': evidence search only. No paid OpenAI calls are made.';}else{status.className='banner '+(r.connected?'info':'warning');
 status.textContent=r.connected
  ? `OpenAI API key configured (not yet tested). App estimate today: $${Number(r.estimated_spend_today_usd).toFixed(4)} across ${r.requests_today} calls. Local daily spending guard: $${Number(r.daily_budget_usd).toFixed(2)}. Actual provider charges may differ.`
  : (meta?.hosted_readonly?(meta.private_preview?'Private local read-only preview: evidence-only; paid AI and data writes disabled.':'Shared management demo: evidence-only. Paid OpenAI and draft uploads are disabled on this host.'):'OPENAI_API_KEY is not configured locally. Evidence-only search is available.');}
 for(const id of ['localModel','localReviewModel']){
  const sel=$(id),old=sel.value;sel.innerHTML='<option value="">'+(id==='localModel'?'Evidence only — no API call':'Choose paid API model')+'</option>'+r.models.map(m=>`<option value="${esc(m)}">${esc(r.model_info?.[m]?.label||m)}</option>`).join('');sel.value=r.models.includes(old)?old:'';
 }
 }catch(e){status.className='banner warning';status.textContent='Could not check API status: '+e.message;}
}
function checksHtml(c){if(!c)return '';
 const bad=[];if(c.invalid_ids?.length)bad.push('Cites IDs that were NOT supplied: '+c.invalid_ids.join(', '));
 if(!c.cites_any_source)bad.push('No source IDs cited');
 if(c.unverified_numbers?.length)bad.push('Numbers not found in supplied counts/excerpts: '+c.unverified_numbers.join(', '));
 if(c.unverified_quotes?.length)bad.push('Quotes not found verbatim in excerpts: '+c.unverified_quotes.map(q=>'“'+q+'”').join(' | '));
 return `<div class="checks ${c.status==='pass'?'pass':'review'}"><strong>Automated answer check: ${c.status==='pass'?'no problems detected':'needs review'}</strong>${bad.length?'<ul>'+bad.map(b=>'<li>'+esc(b)+'</li>').join('')+'</ul>':''}<div class="footnote">${esc(c.note||'')} Cited: ${esc((c.cited_ids||[]).join(', ')||'none')}</div></div>`;}
function evidenceCard(e){const url=safeHref(e.source_url);return `<article class="comment-card"><div class="comment-meta"><span>${esc(e.comment_id)} · ${esc(e.posted_date||'No date')}</span>${url?`<a target="_blank" rel="noopener noreferrer" href="${esc(url)}">Original comment ↗</a>`:''}</div><div class="comment-title">${esc(e.title||e.organization||e.comment_id)}</div><div class="comment-snippet">${esc(e.excerpt)}</div><div class="review-card-sub">${e.records_with_same_text>1?`<span class="pill">${number(e.records_with_same_text)} matching records share this text</span> · `:''}${e.matches_all_terms===false?'<span class="pill alert">partial term match</span> · ':''}Evidence from: ${esc(e.evidence_source==='extracted_attachment'?'extracted attachment':'comment body')} · Attachments listed: ${esc(e.attachment_count||'0')} · <button class="textbutton open-detail" data-id="${esc(e.comment_id)}">Read full comment</button></div></article>`;}
async function localAsk(){const btn=$('localAsk');btn.disabled=true;btn.textContent='Retrieving evidence…';$('localAnswer').textContent=meta.hosted_readonly?'Searching the saved public comments. No paid API calls are available on this site.':'Searching local comments. A paid OpenAI request requires selecting a model and explicit approval.';
 try{const r=await api('/api/local/query',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:$('localQuestion').value,theme_id:$('localTheme').value,model:$('localModel').value,approved:$('openaiConsent').checked})});
 let label=r.method==='provisional_theme_screen'?'Records flagged for selected theme (unvalidated)':'Lexical screening matches — all extracted terms (not unique people)';
 const extra=`${r.any_term_count!=null&&r.any_term_count!==r.match_count?` · ${number(r.any_term_count)} match ANY concept`:''} · ${number(r.distinct_texts)} approximate text groups`;
 const caution=r.needs_broader_search?'<p class="message warning">No comment matches ALL extracted concepts. The larger ANY-concept count is not evidence that commenters discussed those concepts together. Simplify the question or choose a specific theme.</p>':'';
 const sugg=(r.suggested_themes||[]).length?`<p class="footnote">Related screening themes: ${r.suggested_themes.map(t=>`<button class="textbutton" data-theme="${esc(t.id)}">${esc(t.name)}</button>`).join(' · ')}</p>`:'';
 $('localAnswer').innerHTML=`<div class="local-number"><strong>${number(r.match_count)}</strong><span>${esc(label)}${extra} · ${number(r.total_records)} records in the saved snapshot</span></div><p class="footnote">Search concepts: ${(r.search_tokens||[]).map(t=>'“'+esc(t)+'”').join(', ')||'—'}. ${esc(r.qualifier)} ${esc(r.attachment_note)}</p>${caution}${sugg}`+
 (r.llm_summary?`<div class="ai-summary"><strong>OpenAI API summary · ${esc(r.model||'')}</strong>${r.api_usage?.warning?`<p class="message error">${esc(r.api_usage.warning)}</p>`:''}<div class="prewrap">${esc(r.llm_summary)}</div>${checksHtml(r.llm_checks)}<p class="footnote">Generated from the excerpts below; verify all claims. Estimated model charge: $${Number(r.api_usage?.estimated_usd||0).toFixed(5)} (actual billing may differ).</p></div>`:(meta.hosted_readonly?'<p class="footnote">Evidence-only results. No paid OpenAI calls are possible on this public site.</p>':'<p class="footnote">No OpenAI call made. Select a model and authorize transmission to request a paid summary.</p>'))+
 `<h3>Retrieved source evidence (${r.evidence.length} shown)</h3><div class="commentgrid">${r.evidence.map(evidenceCard).join('')||'<p>No matching records.</p>'}</div>`;
 }catch(e){$('localAnswer').textContent='Query could not finish: '+e.message;}finally{btn.disabled=false;btn.textContent='Find evidence and answer';}
}
async function localCompare(){const btn=$('localCompare');btn.disabled=true;btn.textContent='Requesting OpenAI comparison…';$('localCompareResults').textContent='Comparing the draft against selected evidence using a paid OpenAI request.';
 try{const r=await api('/api/local/compare',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({draft:$('draftInput').value,theme_id:$('localReviewTheme').value,model:$('localReviewModel').value,approved:$('draftApiConsent').checked})});
 $('localCompareResults').innerHTML=`<div class="ai-summary"><strong>LLM-assisted ${esc(r.theme)} assessment</strong><p class="footnote">${number(r.provisional_theme_count)} preliminarily flagged records (${number(r.distinct_texts)} approximate text groups); ${r.evidence.length} excerpts supplied to model.</p>${r.api_usage?.warning?`<p class="message error">${esc(r.api_usage.warning)}</p>`:''}<div class="prewrap">${esc(r.assessment)}</div>${checksHtml(r.llm_checks)}<p class="footnote">Estimated model charge: $${Number(r.api_usage?.estimated_usd||0).toFixed(5)}. ${esc(r.warning)}</p></div><h3>Review source evidence</h3><div class="commentgrid">${r.evidence.map(evidenceCard).join('')}</div>`;
 }catch(e){$('localCompareResults').textContent='API comparison unavailable: '+e.message;}finally{btn.disabled=false;btn.textContent='Review this theme with OpenAI API';}
}

