// V10 local staging: a read-only management add-on. Nothing here calls an LLM.
let managementState=null, managementPage=1, managementSection='support', managementRequestId=0;
async function loadManagement(){
 try {
   managementState=await api('/api/management');
   const select=$('mgSection'), current=select.value||managementSection;
   select.innerHTML=managementState.sections.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');
   select.value=managementState.sections.some(s=>s.id===current)?current:'support'; managementSection=select.value;
   $('mgTheme').innerHTML='<option value="">All provisional AI themes</option>'+managementState.themes.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('');
   $('mgStatus').textContent=managementState.status+(managementState.ready?' · Category summaries and 240 category × AI-theme summaries are precompiled offline; search text does not change narratives.':' · Counts and exports are deliberately unavailable until a verified frozen corpus and reviewed category assignments are supplied.');
   $('mgStatus').className='banner '+(managementState.ready?'info':'warning');
   $('mgDownloadCSV').disabled=!managementState.ready;$('mgDownloadWord').disabled=!managementState.ready;$('mgDownloadCodedCSV').disabled=!managementState.ready;$('mgDownloadTopicCSV').disabled=!managementState.ready;$('mgDownloadTopicWord').disabled=!managementState.ready;
   await renderManagement();
 }catch(e){$('mgStatus').textContent='Management add-on unavailable: '+e.message;$('mgStatus').className='banner warning';}
}
async function renderManagement(){
 if(!managementState){await loadManagement();return;}
 const section=$('mgSection').value||managementSection;
 managementSection=section;
 const d=managementState.sections.find(s=>s.id===section);
 if(!d)return;
 $('mgNarrativeTitle').textContent=d.name;
 $('mgNarrative').textContent=d.narrative||'Awaiting source-grounded full-category synthesis from a frozen, reviewed public API snapshot.';
 $('mgRuleDescription').textContent=d.coding_rule_description||'Screening interpretation not supplied.';
 const ol=d.category_overlap||{};
 $('mgOverlapExplanation').textContent=ol.corpus_records?`${number(ol.multiple_substantive_categories)} of ${number(ol.corpus_records)} comments have multiple substantive management categories; ${number(ol.criticism_and_content)} are both Criticism and Content, and ${number(ol.support_and_criticism)} both Support and Criticism. Summary and Questionnaire are reporting views, not exclusive categories. Counts are provisional and do not add to the corpus total.`:'';
 $('mgRuleCodes').innerHTML=(d.coding_rule_code_rows||[]).length?'<h3>Full code definitions in this section</h3><div class="management-rule-table">'+d.coding_rule_code_rows.map(x=>`<div class="management-rule-row"><strong>${esc(x.code)}</strong><span>${esc(x.description)}</span><small>${number(x.records)} flagged submissions</small></div>`).join('')+'</div>':'<p class="footnote">This heading is a reporting view, not a mutually exclusive substantive code.</p>';

 $('mgCitations').innerHTML=(d.evidence_ids||[]).map(cid=>`<button type="button" class="tag open-detail" data-id="${esc(cid)}">${esc(cid)} · View source</button>`).join('');
 $('mgCompiledArguments').innerHTML=(d.compiled_arguments||[]).length ?
    '<h3>Compiled argument families — full section</h3>'+d.compiled_arguments.map(x=>`<div class="management-argument"><div><strong>${esc(x.code)} · ${esc(x.label)}</strong> <span class="muted">${number(x.records)} submissions · ${number(x.text_groups)} approximate text groups</span></div><p>${esc(x.summary||'')}</p><div class="tags">${(x.evidence_ids||[]).slice(0,3).map(cid=>`<button type="button" class="tag open-detail" data-id="${esc(cid)}">${esc(cid)} ↗</button>`).join('')}</div></div>`).join('') : '';
 $('mgRepeatedGroups').innerHTML=(d.compiled_top_clusters||[]).length&&(['support','criticism','content','summary'].includes(section)) ? '<h3>Repeated submissions (counted individually; arguments consolidated)</h3>'+d.compiled_top_clusters.slice(0,3).map(x=>`<div class="metric"><span>${esc(x.subject||x.cluster_id)} <small>${esc(x.cluster_id)}</small></span><strong>${number(x.comment_records)} submissions</strong></div>`).join('') : '';

 const showQs=section==='questionnaire' && (d.questionnaire_sections||[]).length;
 $('mgSubsections').classList.toggle('hide',!showQs);
 if(showQs){let sel=$('mgQuestionnaire'),old=sel.value;sel.innerHTML='<option value="">All questionnaire sections</option>'+d.questionnaire_sections.map(q=>`<option value="${esc(q.name)}">${esc(q.name)}</option>`).join('');sel.value=old;}
 $('mgTopics').innerHTML=(d.subtopics||[]).length?'<h3>Tagged subtopics</h3>'+d.subtopics.map(x=>`<div class="metric"><span>${esc(x.name)}</span><strong>${number(x.assignment_rows)} assignment rows</strong></div>`).join(''):'';
 if(!managementState.ready){$('mgCount').textContent='Count pending · no management tagging has been inferred from old themes';$('mgResults').textContent='Matching comments will appear after classification QC and artifact generation.';$('mgPager').textContent='';return;}
 await managementComments();
}
function showManagementTopicSynthesis(){
 const el=$('mgComboSummary'); const category=$('mgSection').value;const topic=$('mgTheme').value;
 const current=managementState?.topic_combinations?.[category+'::'+topic];
 if(!topic){el.classList.add('hide');el.innerHTML='';$('mgNarrativeTitle').textContent=(managementState?.sections||[]).find(s=>s.id===category)?.name||'Category synthesis';return;}
 el.classList.remove('hide');$('mgNarrativeTitle').textContent='Whole-category synthesis (all AI themes)';
 if(!current){el.textContent='No verified offline synthesis for this management section and AI theme.';return;}
 const sources=(current.source_ids||[]).map(cid=>`<button type="button" class="tag open-detail" data-id="${esc(cid)}">${esc(cid)} ↗</button>`).join('');
 el.innerHTML=`<h3>Precompiled synthesis: ${esc(current.category_label)} × ${esc(current.topic_label)}</h3>
 <p class="muted">${number(current.comment_count)} matching submissions · ${number(current.distinct_text_groups)} approximate text groups · intersection of the selected management section and existing AI theme</p>
 <p class="prewrap">${esc(current.narrative)}</p><div class="tags">${sources}</div>
 <p class="footnote">Offline provisional synthesis; not a human-validated finding. The search box and questionnaire-section filter narrow the records below, but do not regenerate this saved topic summary.</p>`;
}
async function managementComments(){
 if(!managementState?.ready)return;
 showManagementTopicSynthesis();
 const requestId=++managementRequestId;const sec=$('mgSection').value,theme=$('mgTheme').value,q=$('mgQuery').value;
 const extra=(sec==='questionnaire'&&$('mgQuestionnaire').value)?'&questionnaire='+encodeURIComponent($('mgQuestionnaire').value):'';
 try{
 const mgExtra=new URLSearchParams({form_mode:$('mgFormMode').value,topic:$('mgNewTopic').value,relevance:$('mgRelevance').value,content_action:$('mgContentAction').value});
  const r=await api('/api/feedback/records?section='+encodeURIComponent(sec)+'&theme='+encodeURIComponent(theme)+'&q='+encodeURIComponent(q)+'&page='+managementPage+extra+'&'+mgExtra);
 if(requestId!==managementRequestId)return;const def=managementState.sections.find(s=>s.id===sec);
 $('mgCount').textContent=`${number(r.total)} displayed in this view · ${number(r.total_submissions)} matching submissions · ${number(managementState.corpus_records)} corpus records · ${number(r.approximate_distinct_groups)} approximate groups · overlapping categories`; 
 $('mgResults').innerHTML=r.rows.map(x=>`<article class="comment-card"><div class="comment-meta"><span>${esc(x.comment_id)} · ${esc(x.posted_date||'')}</span>${safeHref(x.comment_url)?`<a target="_blank" rel="noopener noreferrer" href="${esc(safeHref(x.comment_url))}">Original ↗</a>`:''}</div><div class="comment-title">${esc(x.title||x.organization||x.comment_id)}</div><div class="comment-snippet">${esc(x.excerpt||'')}</div><div class="review-card-sub">${Number(x.cluster_size||1)>1?esc(x.cluster_size)+' records in this near-duplicate group · ':''}${String(x.management_low_confidence||"0")==="1"?`<span class="tag" title="${esc(x.management_low_confidence_reasons||'Source ambiguity')}">QC QUESTIONABLE</span> · `:""}<button class="textbutton open-detail" data-id="${esc(x.comment_id)}">Read full comment</button></div></article>`).join('')||'No matching comments.';
 const pages=Math.ceil(r.total/r.page_size);$('mgPager').innerHTML=pages>1?`<button id="mgPrev" ${managementPage<=1?'disabled':''}>Previous</button> Page ${number(managementPage)} of ${number(pages)} <button id="mgNext" ${managementPage>=pages?'disabled':''}>Next</button>`:'';
 if($('mgPrev'))$('mgPrev').onclick=()=>{managementPage--;managementComments()};if($('mgNext'))$('mgNext').onclick=()=>{managementPage++;managementComments()};
 }catch(e){if(requestId===managementRequestId)$('mgResults').textContent='Could not load matching comments: '+e.message;}
}

