async function renderFeedback(page=1){
 if(!feedbackOptions){return;}
 feedbackPage=page;
 try{
  const r=await api('/api/feedback/records?'+urlParams({...feedbackParams(),page:feedbackPage,size:20}));
  $('fbMetrics').innerHTML=[
    metric('Source submissions matching filters',number(r.total_submissions)),
    metric('Records displayed in selected form view',number(r.matching_records)),
    metric('Approximate text groups',number(r.approximate_distinct_groups)),
    metric('Exact repeated text',number(r.exact_repeated_text)),
    metric('Likely form letters',number(r.likely_form_letter)),
    metric('Not flagged',number(r.not_flagged)),
    metric('Personalized submissions in groups',number(r.personalized_in_matching))
  ].join('');
  $('fbLimitations').textContent=r.limitations+' '+r.narrative_scope;
  $('fbResults').innerHTML=r.rows.map(x=>{
   const tags=Object.entries(x.new_topics||{}).map(([k,v])=>'<span class="tag">'+esc(v.name)+' · '+esc(v.relevance)+'</span>').join(' ');
   const flag=x.form_flag==='exact_repeated_text'?'Exact repeated text':x.form_flag==='likely_form_letter'?'Likely form letter':'Not flagged';
   return '<article class="comment-card"><div class="comment-meta">'+esc(x.comment_id)+
    (safeHref(x.comment_url)?' · <a target="_blank" rel="noopener noreferrer" href="'+esc(safeHref(x.comment_url))+'">Source ↗</a>':'')+
    '</div><div class="comment-title">'+esc(x.title||x.organization||x.comment_id)+
    '</div><div class="comment-snippet">'+esc(x.excerpt||'')+'</div><div class="review-card-sub"><strong>'+
    esc(flag)+'</strong>'+(x.form_personalized?' · Customized/personal text detected':'')+
    (x.supports_measure?' · Supports a specific measure':'')+'</div><div class="tags">'+tags+
    '</div><button class="textbutton open-detail" data-id="'+esc(x.comment_id)+'">View full source and original tags</button></article>';
  }).join('')||'<p class="muted">No matching source records.</p>';
  const pages=Math.ceil(r.total/r.page_size);
  $('fbPager').innerHTML=pages>1?'<button id="fbPrev" '+(feedbackPage<=1?'disabled':'')+'>Previous</button> Page '+number(feedbackPage)+' of '+number(pages)+' <button id="fbNext" '+(feedbackPage>=pages?'disabled':'')+'>Next</button>':'';
  if($('fbPrev'))$('fbPrev').onclick=()=>renderFeedback(feedbackPage-1);
  if($('fbNext'))$('fbNext').onclick=()=>renderFeedback(feedbackPage+1);
 }catch(e){$('fbResults').textContent='Could not filter comments: '+e.message;}
}
